import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { nextOrderReturnSortDirection, sortOrdersByNetReturn, type OrderReturnSortDirection } from "@/lib/orderReturnSort";
import { trpc } from "@/lib/trpc";
import { ArrowLeft, BarChart3, DatabaseZap, Loader2, RefreshCw, ShieldAlert, ShieldCheck, WalletCards } from "lucide-react";
import { useMemo, useState } from "react";
import { CartesianGrid, Legend, Line, LineChart, ResponsiveContainer, Tooltip, XAxis, YAxis } from "recharts";
import { Link } from "wouter";

function formatMoney(value: number) { return new Intl.NumberFormat("zh-CN", { maximumFractionDigits: 0 }).format(value); }
function formatDate(date: string | null) { return date ? date.replace(/^(\d{4})-(\d{2})-(\d{2})$/, "$1年$2月$3日") : "-"; }
function Metric({ label, value, tone = "text-slate-800" }: { label: string; value: string; tone?: string }) { return <div className="rounded-xl border border-slate-200 bg-white p-4 shadow-sm"><p className="text-xs text-slate-500">{label}</p><p className={`mt-1 text-lg font-bold ${tone}`}>{value}</p></div>; }
function ReturnLineChart({ data, series }: { data: Array<Record<string, string | number>>; series: Array<{ key: string; label: string; color: string }> }) { return <div className="mt-5 h-[330px] w-full"><ResponsiveContainer width="100%" height="100%"><LineChart data={data} margin={{ top: 12, right: 20, bottom: 8, left: -8 }}><CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" vertical={false} /><XAxis dataKey="date" minTickGap={24} tick={{ fontSize: 11, fill: "#64748b" }} /><YAxis tick={{ fontSize: 11, fill: "#64748b" }} tickFormatter={(value) => `${value}%`} /><Tooltip formatter={(value) => [`${value}%`, "累计收益率"]} /><Legend wrapperStyle={{ fontSize: 12 }} />{series.map((item) => <Line key={item.key} type="monotone" dataKey={item.key} name={item.label} stroke={item.color} strokeWidth={2.25} dot={false} activeDot={{ r: 4 }} isAnimationActive={false} connectNulls />)}</LineChart></ResponsiveContainer></div>; }
type TradeDiffSnapshot = { status: "filled" | "skipped"; score: number; shares: number; entryDate: string | null; exitDate: string | null; entryPrice: number | null; exitPrice: number | null; netReturn: number | null; reason: string | null };
type OrderStrategyKey = "baseline" | "riskPenalty" | "hardFilter";
type SimulatedOrder = { signalDate: string; entryDate: string | null; exitDate: string | null; stockCode: string; stockName: string; score: number; shares: number; entryPrice: number | null; exitPrice: number | null; netReturn: number | null; entryPointPremium?: number | null; status: "filled" | "skipped"; reason: string | null; highRiskExcluded?: boolean };
const orderStrategyOptions: Array<{ key: OrderStrategyKey; label: string; description: string }> = [
  { key: "baseline", label: "原始评分基准", description: "保留原始候选评分与全部模拟订单。" },
  { key: "riskPenalty", label: "风险扣分策略", description: "按自动/回退风险权重重新排序后的完整模拟订单。" },
  { key: "hardFilter", label: "高风险硬过滤", description: "同时展示实际模拟订单和因高风险被排除的未入场订单。" },
];
function TradeDiffCell({ trade, filtered = false }: { trade: TradeDiffSnapshot | null; filtered?: boolean }) { if (filtered) return <div className="min-w-44 rounded-lg bg-amber-50 p-2 text-amber-800"><p className="font-semibold">高风险过滤</p><p className="mt-1 text-slate-500">风险分达到阈值，未进入模拟</p></div>; if (!trade) return <span className="text-slate-400">无订单</span>; return <div className="min-w-44 rounded-lg bg-slate-50 p-2"><p className={`font-semibold ${trade.status === "filled" ? "text-slate-800" : "text-amber-700"}`}>{trade.status === "filled" ? "已入场" : "未入场"} · 评分 {trade.score}</p><p className="mt-1 text-slate-500">{formatDate(trade.entryDate)} → {formatDate(trade.exitDate)}</p><p className="mt-1 text-slate-500">{trade.entryPrice ?? "-"} / {trade.exitPrice ?? "-"} · {trade.shares || "-"}股</p><p className={`mt-1 font-semibold ${trade.netReturn !== null && trade.netReturn >= 0 ? "text-rose-600" : "text-emerald-700"}`}>{trade.netReturn === null ? "收益待定" : `${trade.netReturn}%`}</p><p className="mt-1 leading-4 text-slate-500">{trade.reason ?? "-"}</p></div>; }

function FullOrdersSection({
  strategy,
  onStrategyChange,
  activeStrategy,
  orders,
  displayedOrders,
  orderStatus,
  onOrderStatusChange,
  reason,
  onReasonChange,
  reasons,
  keyword,
  onKeywordChange,
  returnSortDirection,
  onReturnSortDirectionChange,
}: {
  strategy: OrderStrategyKey;
  onStrategyChange: (strategy: OrderStrategyKey) => void;
  activeStrategy: (typeof orderStrategyOptions)[number];
  orders: SimulatedOrder[];
  displayedOrders: SimulatedOrder[];
  orderStatus: "all" | "filled" | "skipped";
  onOrderStatusChange: (status: "all" | "filled" | "skipped") => void;
  reason: string;
  onReasonChange: (reason: string) => void;
  reasons: string[];
  keyword: string;
  onKeywordChange: (keyword: string) => void;
  returnSortDirection: OrderReturnSortDirection;
  onReturnSortDirectionChange: (direction: OrderReturnSortDirection) => void;
}) {
  const filledCount = orders.filter((order) => order.status === "filled").length;
  const skippedCount = orders.length - filledCount;
  const highRiskExcludedCount = orders.filter((order) => order.highRiskExcluded).length;

  return (
    <section data-all-simulated-orders className="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm">
      <div className="mb-4 flex flex-col gap-4 border-b border-slate-100 pb-4">
        <div className="flex flex-wrap items-start gap-3">
          <div className="mr-auto">
            <h2 className="font-semibold">全部模拟订单</h2>
            <p className="mt-1 text-xs text-slate-500">切换后展示对应全周期策略的全部订单；红涨绿跌。</p>
          </div>
          <div className="flex rounded-lg border border-slate-200 bg-slate-50 p-1" role="tablist" aria-label="订单策略切换">
            {orderStrategyOptions.map((option) => (
              <Button
                key={option.key}
                type="button"
                size="sm"
                variant={strategy === option.key ? "default" : "ghost"}
                role="tab"
                aria-selected={strategy === option.key}
                onClick={() => onStrategyChange(option.key)}
                className={strategy === option.key ? "bg-slate-800 text-white hover:bg-slate-700" : "text-slate-600"}
              >
                {option.label}
              </Button>
            ))}
          </div>
        </div>
        <div className="flex flex-wrap items-end gap-3">
          <div className="mr-auto">
            <p className="text-sm font-medium text-slate-800">{activeStrategy.label}</p>
            <p className="mt-1 text-xs text-slate-500">{activeStrategy.description}</p>
            <p className="mt-2 text-xs text-slate-600">显示 {displayedOrders.length}/{orders.length} 笔 · 已入场 {filledCount} 笔 · 未入场 {skippedCount} 笔{strategy === "hardFilter" && ` · 高风险剔除 ${highRiskExcludedCount} 笔`}</p>
          </div>
          <label className="text-xs text-slate-600">状态<select value={orderStatus} onChange={(event) => onOrderStatusChange(event.target.value as "all" | "filled" | "skipped")} className="mt-1 block h-8 rounded-md border border-slate-200 px-2"><option value="all">全部</option><option value="filled">已入场</option><option value="skipped">未入场</option></select></label>
          <label className="text-xs text-slate-600">原因<select value={reason} onChange={(event) => onReasonChange(event.target.value)} className="mt-1 block h-8 max-w-52 rounded-md border border-slate-200 px-2"><option value="all">全部</option>{reasons.map((value) => <option key={value} value={value}>{value}</option>)}</select></label>
          <label className="text-xs text-slate-600">搜索<Input value={keyword} onChange={(event) => onKeywordChange(event.target.value)} placeholder="代码或名称" className="mt-1 h-8 w-36" /></label>
        </div>
      </div>
      <div className="orders-scroll-container overflow-auto rounded-lg border border-slate-200">
        <table className="w-full min-w-[1220px] text-xs">
          <thead className="bg-slate-100 text-left text-slate-500">
            <tr><th className="px-3 py-2">信号日</th><th className="px-3 py-2">股票</th><th className="px-3 py-2">评分</th><th className="px-3 py-2">状态</th><th className="px-3 py-2">股数</th><th className="px-3 py-2">买入/卖出日</th><th className="px-3 py-2">买入/卖出价</th><th className="px-3 py-2"><button type="button" className="inline-flex items-center gap-1 rounded px-1 py-0.5 font-semibold text-slate-600 transition-colors hover:bg-slate-200 hover:text-slate-900 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-sky-500" onClick={() => onReturnSortDirectionChange(nextOrderReturnSortDirection(returnSortDirection))} aria-label={`按收益率${returnSortDirection === "desc" ? "升序" : "降序"}排列`} aria-sort={returnSortDirection === "asc" ? "ascending" : returnSortDirection === "desc" ? "descending" : "none"}>收益率 <span aria-hidden="true" className={returnSortDirection === "none" ? "text-slate-400" : "text-sky-700"}>{returnSortDirection === "asc" ? "↑" : returnSortDirection === "desc" ? "↓" : "↕"}</span></button></th><th className="px-3 py-2">买点涨幅</th><th className="px-3 py-2">原因</th></tr>
          </thead>
          <tbody>
            {displayedOrders.map((order, index) => {
              const entryPointPremium = order.entryPointPremium ?? null;
              return <tr key={`${strategy}-${order.signalDate}-${order.stockCode}-${index}`} className="border-t border-slate-100 align-top"><td className="whitespace-nowrap px-3 py-2">{formatDate(order.signalDate)}</td><td className="px-3 py-2"><p className="font-medium">{order.stockName}</p><p className="font-mono text-slate-400">{order.stockCode}</p></td><td className="px-3 py-2 font-medium text-slate-700">{order.score}</td><td className="px-3 py-2">{order.highRiskExcluded ? <span className="rounded bg-amber-100 px-1.5 py-0.5 font-medium text-amber-800">高风险剔除</span> : order.status === "filled" ? "已成交" : "未成交"}</td><td className="px-3 py-2">{order.shares || "-"}</td><td className="whitespace-nowrap px-3 py-2">{formatDate(order.entryDate)} / {formatDate(order.exitDate)}</td><td className="whitespace-nowrap px-3 py-2">{order.entryPrice ?? "-"} / {order.exitPrice ?? "-"}</td><td className={`px-3 py-2 font-medium ${order.netReturn !== null && order.netReturn >= 0 ? "text-rose-600" : "text-emerald-700"}`}>{order.netReturn === null ? "-" : `${order.netReturn}%`}</td><td className={`px-3 py-2 font-medium ${entryPointPremium !== null && entryPointPremium >= 0 ? "text-rose-600" : "text-emerald-700"}`}>{entryPointPremium === null ? "-" : `${entryPointPremium}%`}</td><td className="max-w-80 px-3 py-2 leading-5 text-slate-500">{order.reason ?? "-"}</td></tr>;
            })}
          </tbody>
        </table>
        {displayedOrders.length === 0 && <p className="p-6 text-center text-sm text-slate-500">没有符合当前筛选条件的订单。</p>}
      </div>
    </section>
  );
}

export default function BacktestPage() {
  const [config, setConfig] = useState({
    initialCapital: 100000, maxPositions: 5, commissionBps: 3, stampDutyBps: 5, transferFeeBps: 0.1, slippageBps: 10,
    blockLimitUpBuys: false, blockLimitDownSells: false, enableOneWordLimitDownProbability: false, oneWordLimitDownSellProbability: 0,
    positionSizingStrategy: "equal" as "equal" | "scoreWeighted" | "fixedPercent", fixedPositionPercent: 20, minimumExpectedOpenChangePercent: -2,
    trailingProfitActivationPercent: 6, trailingDrawdownPercent: 3, stopLossPercent: 5, strongHoldMinReturn: 3, maxHoldingDays: 5,
    downsideObservationDays: 5, mediumDownsidePercent: 4, highDownsidePercent: 8, riskPenaltyWeight: 0.35, autoTunePenaltyWeight: true, hardRiskThreshold: 65, rollingTrainTradingDays: 45, rollingValidationTradingDays: 14,
  });
  const [orderStatus, setOrderStatus] = useState<"all" | "filled" | "skipped">("all");
  const [reason, setReason] = useState("all");
  const [keyword, setKeyword] = useState("");
  const [tradeDiffOnly, setTradeDiffOnly] = useState(true);
  const [tradeDiffKeyword, setTradeDiffKeyword] = useState("");
  const [orderStrategy, setOrderStrategy] = useState<OrderStrategyKey>("baseline");
  const [orderReturnSortDirection, setOrderReturnSortDirection] = useState<OrderReturnSortDirection>("none");
  const update = <K extends keyof typeof config>(key: K, value: (typeof config)[K]) => setConfig((current) => ({ ...current, [key]: value }));
  const input = useMemo(() => ({
    observationDays: 1 as const,
    realistic: {
      initialCapital: config.initialCapital, maxPositions: config.maxPositions, commissionRate: config.commissionBps / 10000, stampDutyRate: config.stampDutyBps / 10000, transferFeeRate: config.transferFeeBps / 10000, slippageBps: config.slippageBps,
      blockLimitUpBuys: config.blockLimitUpBuys, blockLimitDownSells: config.blockLimitDownSells, enableOneWordLimitDownProbability: config.enableOneWordLimitDownProbability, oneWordLimitDownSellProbability: config.oneWordLimitDownSellProbability,
      positionSizingStrategy: config.positionSizingStrategy, fixedPositionPercent: config.fixedPositionPercent, minimumExpectedOpenChangePercent: config.minimumExpectedOpenChangePercent,
      trailingProfitActivationPercent: config.trailingProfitActivationPercent, trailingDrawdownPercent: config.trailingDrawdownPercent, stopLossPercent: config.stopLossPercent, strongHoldMinReturn: config.strongHoldMinReturn, maxHoldingDays: config.maxHoldingDays,
    },
    downsideRisk: {
      observationDays: config.downsideObservationDays, mediumDownsidePercent: config.mediumDownsidePercent, highDownsidePercent: config.highDownsidePercent, penaltyWeight: config.riskPenaltyWeight, autoTunePenaltyWeight: config.autoTunePenaltyWeight, hardRiskThreshold: config.hardRiskThreshold,
      rollingTrainTradingDays: config.rollingTrainTradingDays, rollingValidationTradingDays: config.rollingValidationTradingDays,
    },
  }), [config]);
  const { data, isLoading, isFetching, refetch } = trpc.sentiment.getLeaderCandidateBacktest.useQuery(input, { staleTime: 5 * 60_000 });
  const simulation = data?.realisticSimulation;
  const downsideRiskResearch = data?.downsideRiskResearch;
  const dailyPriceCoverage = data?.dailyPriceCoverage;
  const marketFactorCoverage = data?.marketFactorCoverage;
  const walkForwardRiskPenalty = downsideRiskResearch?.walkForward?.experiments.find((experiment) => experiment.key === "riskPenalty");
  const walkForwardBaseline = downsideRiskResearch?.walkForward?.experiments.find((experiment) => experiment.key === "baseline");
  const fullCycleExperiments = downsideRiskResearch?.fullCycle.experiments ?? [];
  const riskPenaltyAttribution = downsideRiskResearch?.fullCycle.riskPenaltyAttribution;
  const factorAblations = downsideRiskResearch?.factorAblations ?? [];
  const fullCycleTradeDifferences = downsideRiskResearch?.fullCycle.tradeDifferences ?? [];
  const fullCycleOrdersByStrategy = useMemo(() => {
    const sortOrders = (items: SimulatedOrder[]) => [...items].sort((left, right) => right.signalDate.localeCompare(left.signalDate) || left.stockCode.localeCompare(right.stockCode));
    const ordersByStrategy = new Map<OrderStrategyKey, SimulatedOrder[]>();
    for (const key of ["baseline", "riskPenalty", "hardFilter"] as const) {
      ordersByStrategy.set(key, fullCycleExperiments.find((experiment) => experiment.key === key)?.realisticSimulation.trades ?? []);
    }
    const hardFilterOrders = ordersByStrategy.get("hardFilter") ?? [];
    const hardFilterOrderKeys = new Set(hardFilterOrders.map((order) => `${order.signalDate}::${order.stockCode}`));
    const excludedOrders: SimulatedOrder[] = fullCycleTradeDifferences
      .filter((row) => row.hardFilterExcluded && !hardFilterOrderKeys.has(`${row.signalDate}::${row.stockCode}`))
      .map((row) => ({
        signalDate: row.signalDate,
        entryDate: null,
        exitDate: null,
        stockCode: row.stockCode,
        stockName: row.stockName,
        score: row.hardFilter?.score ?? row.baseline?.score ?? row.riskPenalty?.score ?? 0,
        shares: 0,
        entryPrice: null,
        exitPrice: null,
        netReturn: null,
        entryPointPremium: null,
        status: "skipped",
        reason: `风险分 ${row.riskScore} 达到硬过滤阈值，未进入模拟`,
        highRiskExcluded: true,
      }));
    ordersByStrategy.set("hardFilter", sortOrders([...hardFilterOrders, ...excludedOrders]));
    ordersByStrategy.set("baseline", sortOrders(ordersByStrategy.get("baseline") ?? []));
    ordersByStrategy.set("riskPenalty", sortOrders(ordersByStrategy.get("riskPenalty") ?? []));
    return ordersByStrategy;
  }, [fullCycleExperiments, fullCycleTradeDifferences]);
  const orders = fullCycleOrdersByStrategy.get(orderStrategy) ?? (orderStrategy === "baseline" ? simulation?.trades ?? [] : []);
  const activeOrderStrategy = orderStrategyOptions.find((item) => item.key === orderStrategy)!;
  const reasons = useMemo(() => Array.from(new Set(orders.map((order) => order.reason).filter((value): value is string => Boolean(value)))).sort(), [orders]);
  const filteredOrders = useMemo(() => {
    const search = keyword.trim().toLowerCase();
    return orders.filter((order) => (orderStatus === "all" || order.status === orderStatus) && (reason === "all" || order.reason === reason) && (!search || `${order.stockCode} ${order.stockName}`.toLowerCase().includes(search)));
  }, [keyword, orderStatus, orders, reason]);
  const displayedOrders = useMemo(() => sortOrdersByNetReturn(filteredOrders, orderReturnSortDirection), [filteredOrders, orderReturnSortDirection]);
  const buildCurve = (items: Array<{ key: string; realisticSimulation: { equityCurve: Array<{ date: string; equity: number }>; initialCapital: number } }>, startDate?: string | null) => {
    const dates = Array.from(new Set(items.flatMap((item) => item.realisticSimulation.equityCurve.map((point) => point.date)))).sort().filter((date) => !startDate || date >= startDate);
    return dates.map((date) => {
      const point: Record<string, string | number> = { date: date.slice(5) };
      for (const item of items) {
        const equity = item.realisticSimulation.equityCurve.find((curvePoint) => curvePoint.date === date)?.equity;
        if (equity !== undefined) point[item.key] = Number((((equity / item.realisticSimulation.initialCapital) - 1) * 100).toFixed(2));
      }
      return point;
    });
  };
  const downsideRiskCurve = useMemo(() => buildCurve((downsideRiskResearch?.experiments ?? []).map((item) => ({ key: item.key, realisticSimulation: item.realisticSimulation }))), [downsideRiskResearch]);
  const fullCycleRiskCurve = useMemo(() => buildCurve(fullCycleExperiments.map((item) => ({ key: item.key, realisticSimulation: item.realisticSimulation })), downsideRiskResearch?.fullCycle.startDate), [downsideRiskResearch?.fullCycle.startDate, fullCycleExperiments]);
  const displayedTradeDifferences = useMemo(() => {
    const search = tradeDiffKeyword.trim().toLowerCase();
    const signature = (trade: TradeDiffSnapshot | null) => trade ? [trade.status, trade.score, trade.shares, trade.entryDate, trade.exitDate, trade.entryPrice, trade.exitPrice, trade.netReturn, trade.reason].join("|") : "";
    return fullCycleTradeDifferences.filter((row) => {
      const hasDifference = row.hardFilterExcluded || new Set([signature(row.baseline), signature(row.riskPenalty), signature(row.hardFilter)]).size > 1;
      const matchesSearch = !search || `${row.stockCode} ${row.stockName} ${row.signalDate}`.toLowerCase().includes(search);
      return matchesSearch && (!tradeDiffOnly || hasDifference);
    });
  }, [fullCycleTradeDifferences, tradeDiffKeyword, tradeDiffOnly]);
  const sortedFactorAblations = useMemo(() => [...factorAblations].sort((left, right) => left.walkForward.drawdownDelta - right.walkForward.drawdownDelta || right.walkForward.returnDelta - left.walkForward.returnDelta), [factorAblations]);
  const stableNegativeFactors = useMemo(() => factorAblations.filter((factor) => factor.fullCycle.returnDelta > 0 && factor.fullCycle.drawdownDelta < 0 && factor.walkForward.returnDelta > 0 && factor.walkForward.drawdownDelta < 0), [factorAblations]);
  const fullCycleOnlyNegativeFactors = useMemo(() => factorAblations.filter((factor) => factor.fullCycle.returnDelta > 0 && factor.fullCycle.drawdownDelta < 0 && !(factor.walkForward.returnDelta > 0 && factor.walkForward.drawdownDelta < 0)), [factorAblations]);
  const rollingWindows = downsideRiskResearch?.rollingWindows ?? [];
  const rollingRiskStability = useMemo(() => {
    if (rollingWindows.length === 0) return null;
    const distribution = new Map<number, number>();
    let positiveRiskPenaltyWindows = 0;
    let outperformingWindows = 0;
    for (const window of rollingWindows) {
      distribution.set(window.autoTunedPenaltyWeight, (distribution.get(window.autoTunedPenaltyWeight) ?? 0) + 1);
      const baseline = window.experiments.find((experiment) => experiment.key === "baseline")?.realisticSimulation;
      const riskPenalty = window.experiments.find((experiment) => experiment.key === "riskPenalty")?.realisticSimulation;
      if (riskPenalty && riskPenalty.totalReturn > 0) positiveRiskPenaltyWindows += 1;
      if (baseline && riskPenalty && riskPenalty.totalReturn > baseline.totalReturn && riskPenalty.maxDrawdown <= baseline.maxDrawdown) outperformingWindows += 1;
    }
    return { positiveRiskPenaltyWindows, outperformingWindows, distribution: Array.from(distribution.entries()).sort(([left], [right]) => left - right).map(([weight, count]) => `${weight}×${count}`).join("、") };
  }, [rollingWindows]);

  return <main className="min-h-screen bg-slate-50 pb-12 text-slate-900">
    <header className="sticky top-0 z-20 border-b border-slate-200 bg-white/95 backdrop-blur"><div className="mx-auto flex max-w-7xl items-center justify-between px-4 py-3 sm:px-6"><Link href="/leader-candidates" className="flex items-center gap-2 text-sm font-medium text-slate-600 hover:text-slate-900"><ArrowLeft className="h-4 w-4" />返回龙头候选池</Link><Button size="sm" variant="outline" className="gap-2" onClick={() => void refetch()} disabled={isFetching}><RefreshCw className={`h-4 w-4 ${isFetching ? "animate-spin" : ""}`} />刷新回测</Button></div></header>
    {downsideRiskResearch?.fullCycle && <section data-full-cycle-comparison className="mx-auto max-w-7xl px-4 pt-5 sm:px-6"><div className="rounded-2xl border border-violet-200 bg-white p-5 shadow-sm"><div className="flex flex-wrap items-start gap-3"><BarChart3 className="mt-0.5 h-5 w-5 text-violet-700" /><div className="mr-auto"><p className="text-xs font-bold tracking-[0.16em] text-violet-700">FULL-CYCLE COMPARISON</p><h2 className="mt-1 font-semibold">全周期三策略收益对比</h2><p className="mt-1 max-w-4xl text-xs leading-5 text-slate-600">{downsideRiskResearch.fullCycle.definition} 覆盖信号日 {downsideRiskResearch.fullCycle.startDate ?? "-"} 至 {downsideRiskResearch.fullCycle.endDate ?? "-"}。</p></div></div><div className="mt-4 grid gap-3 sm:grid-cols-3">{fullCycleExperiments.map((experiment) => <div key={experiment.key} className="rounded-xl border border-slate-200 bg-slate-50 p-4 shadow-sm"><p className="text-xs text-slate-500">{experiment.label} · 全周期累计收益</p><p className={`mt-1 text-lg font-bold ${experiment.realisticSimulation.totalReturn >= 0 ? "text-rose-600" : "text-emerald-700"}`}>{experiment.realisticSimulation.totalReturn}%</p><div className="mt-2 flex gap-4 text-xs"><span className="text-slate-500">最大回撤 <b className="text-emerald-700">{experiment.realisticSimulation.maxDrawdown}%</b></span><span className="text-slate-500">已出清 <b className="text-slate-700">{experiment.realisticSimulation.completedCount}</b></span></div></div>)}</div><ReturnLineChart data={fullCycleRiskCurve} series={fullCycleExperiments.map((item) => ({ key: item.key, label: item.label, color: item.key === "baseline" ? "#64748b" : item.key === "riskPenalty" ? "#d946ef" : "#f59e0b" }))} /><div data-trade-difference-table className="mt-6 rounded-xl border border-violet-100"><div className="flex flex-wrap items-end gap-3 border-b border-violet-100 bg-violet-50/60 px-4 py-3"><div className="mr-auto"><h3 className="text-sm font-semibold text-violet-950">逐笔交易差异对比</h3><p className="mt-1 text-xs text-violet-800">按相同信号日与股票对齐；每格依次展示状态、评分、买卖日期/价格/股数、收益率和原因。高风险过滤未进入模拟时单独标记。</p></div><label className="flex items-center gap-2 text-xs font-medium text-violet-900"><input type="checkbox" checked={tradeDiffOnly} onChange={(event) => setTradeDiffOnly(event.target.checked)} />仅看有差异订单</label><label className="text-xs text-slate-600">搜索<Input value={tradeDiffKeyword} onChange={(event) => setTradeDiffKeyword(event.target.value)} placeholder="代码、名称或日期" className="mt-1 h-8 w-40 bg-white" /></label></div><div className="overflow-auto"><table className="w-full min-w-[1500px] text-xs"><thead className="bg-white text-left text-slate-500"><tr><th className="px-3 py-2">信号日 / 股票</th><th className="px-3 py-2">风险分 / 扣分权重</th><th className="px-3 py-2">原始评分基准</th><th className="px-3 py-2">风险扣分策略</th><th className="px-3 py-2">高风险硬过滤</th></tr></thead><tbody>{displayedTradeDifferences.map((row) => <tr key={`${row.signalDate}-${row.stockCode}`} className="border-t border-slate-100 align-top"><td className="px-3 py-3"><p className="font-medium text-slate-800">{row.stockName}</p><p className="mt-1 font-mono text-slate-500">{row.stockCode}</p><p className="mt-1 text-slate-500">{row.signalDate}</p></td><td className="px-3 py-3"><p className="font-semibold text-fuchsia-800">风险 {row.riskScore}</p><p className="mt-1 text-slate-500">权重 {row.appliedPenaltyWeight}</p></td><td className="px-3 py-3"><TradeDiffCell trade={row.baseline} /></td><td className="px-3 py-3"><TradeDiffCell trade={row.riskPenalty} /></td><td className="px-3 py-3"><TradeDiffCell trade={row.hardFilter} filtered={row.hardFilterExcluded} /></td></tr>)}</tbody></table>{displayedTradeDifferences.length === 0 && <p className="p-6 text-center text-sm text-slate-500">没有符合当前筛选条件的订单。</p>}</div></div></div></section>}
    {downsideRiskResearch?.walkForward && <section data-walk-forward className="mx-auto max-w-7xl px-4 pt-5 sm:px-6"><div className="rounded-2xl border border-fuchsia-200 bg-white p-5 shadow-sm"><div className="flex flex-wrap items-start gap-3"><DatabaseZap className="mt-0.5 h-5 w-5 text-fuchsia-700" /><div className="mr-auto"><h2 className="font-semibold">样本外累计拼接曲线</h2><p className="mt-1 max-w-4xl text-xs leading-5 text-slate-600">{downsideRiskResearch.walkForward.definition} 覆盖 {downsideRiskResearch.walkForward.validationWindowCount} 个连续验证窗口（{downsideRiskResearch.walkForward.startDate ?? "-"} 至 {downsideRiskResearch.walkForward.endDate ?? "-"}）。</p></div></div><div className="mt-4 grid gap-3 sm:grid-cols-3">{downsideRiskResearch.walkForward.experiments.map((experiment) => <div key={experiment.key} className="rounded-xl border border-slate-200 bg-slate-50 p-4 shadow-sm"><p className="text-xs text-slate-500">{experiment.label} · 样本外累计收益</p><p className={`mt-1 text-lg font-bold ${experiment.totalReturn >= 0 ? "text-rose-600" : "text-emerald-700"}`}>{experiment.totalReturn}%</p><div className="mt-2 flex gap-4 text-xs"><span className="text-slate-500">最大回撤 <b className="text-emerald-700">{experiment.maxDrawdown}%</b></span><span className="text-slate-500">已出清 <b className="text-slate-700">{experiment.completedCount}</b></span></div></div>)}</div><ReturnLineChart data={downsideRiskResearch.walkForward.equityCurve.map((point) => ({ date: point.date.slice(5), ...(point.baseline === null ? {} : { baseline: point.baseline }), ...(point.riskPenalty === null ? {} : { riskPenalty: point.riskPenalty }), ...(point.hardFilter === null ? {} : { hardFilter: point.hardFilter }) }))} series={[{ key: "baseline", label: "原始策略", color: "#64748b" }, { key: "riskPenalty", label: "风险扣分", color: "#d946ef" }, { key: "hardFilter", label: "高风险过滤", color: "#f59e0b" }]} /></div></section>}
    {rollingRiskStability && <section data-ten-window-stability className="mx-auto max-w-7xl px-4 pt-5 sm:px-6"><div className="rounded-2xl border border-indigo-200 bg-white p-5 shadow-sm"><div className="flex items-start gap-3"><BarChart3 className="mt-0.5 h-5 w-5 text-indigo-700" /><div><p className="text-xs font-bold tracking-[0.16em] text-indigo-700">GENERALIZATION CHECK</p><h2 className="mt-1 font-semibold">{rollingWindows.length}窗口样本外泛化稳定性</h2><p className="mt-1 text-xs leading-5 text-slate-600">每个窗口均只由其前置训练期选权；“相对优胜”要求风险扣分策略在该窗口同时实现更高收益与不更高的最大回撤。</p></div></div><div className="mt-4 grid gap-3 sm:grid-cols-3"><Metric label="风险扣分正收益窗口" value={`${rollingRiskStability.positiveRiskPenaltyWindows} / ${rollingWindows.length}`} tone="text-rose-600" /><Metric label="相对原始优胜窗口" value={`${rollingRiskStability.outperformingWindows} / ${rollingWindows.length}`} tone="text-indigo-700" /><Metric label="训练期选中权重分布" value={rollingRiskStability.distribution} /></div></div></section>}
    {riskPenaltyAttribution && <section data-risk-penalty-attribution className="mx-auto max-w-7xl px-4 pt-5 sm:px-6"><div className="rounded-2xl border border-amber-200 bg-white p-5 shadow-sm"><div className="flex flex-wrap items-start gap-3"><ShieldAlert className="mt-0.5 h-5 w-5 text-amber-700" /><div className="mr-auto"><p className="text-xs font-bold tracking-[0.16em] text-amber-700">PERFORMANCE ATTRIBUTION</p><h2 className="mt-1 font-semibold">风险扣分策略表现归因</h2><p className="mt-1 max-w-4xl text-xs leading-5 text-slate-600">风险扣分不直接降低仓位，而会重排同日候选优先级；在最大持仓和现金约束下，资金会由原始策略已成交的股票转向其他候选。因此，全周期收益差异主要来自订单替换，而非共同持仓的买卖规则不同。</p></div></div><div className="mt-4 grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><Metric label="原始独有成交" value={`${riskPenaltyAttribution.baselineOnlyFilledCount} 笔 / ¥${formatMoney(riskPenaltyAttribution.baselineOnlyNetPnl)}`} tone={riskPenaltyAttribution.baselineOnlyNetPnl >= 0 ? "text-rose-600" : "text-emerald-700"} /><Metric label="扣分独有成交" value={`${riskPenaltyAttribution.riskPenaltyOnlyFilledCount} 笔 / ¥${formatMoney(riskPenaltyAttribution.riskPenaltyOnlyNetPnl)}`} tone={riskPenaltyAttribution.riskPenaltyOnlyNetPnl >= 0 ? "text-rose-600" : "text-emerald-700"} /><Metric label="共同成交 / 收益差异" value={`${riskPenaltyAttribution.commonFilledCount} / ${riskPenaltyAttribution.commonFilledDifferentReturnCount} 笔`} /><Metric label="自动 / 回退权重信号" value={`${riskPenaltyAttribution.autoTunedSignalCount} / ${riskPenaltyAttribution.fallbackWeightSignalCount}`} /></div><p className="mt-4 text-xs leading-5 text-slate-600">本次全周期内，扣分独有订单的净利润若低于原始独有订单，风险扣分版就会同时拖累累计收益和资金高点后的回撤。严格样本外验证则应以滚动拼接结果为准：原始 {walkForwardBaseline?.totalReturn ?? "-"}% / 回撤 {walkForwardBaseline?.maxDrawdown ?? "-"}%，风险扣分 {walkForwardRiskPenalty?.totalReturn ?? "-"}% / 回撤 {walkForwardRiskPenalty?.maxDrawdown ?? "-"}%。</p></div></section>}
    {factorAblations.length > 0 && <section data-factor-ablation className="mx-auto max-w-7xl px-4 pt-5 sm:px-6"><div className="rounded-2xl border border-cyan-200 bg-white p-5 shadow-sm"><div className="flex items-start gap-3"><DatabaseZap className="mt-0.5 h-5 w-5 text-cyan-700" /><div><p className="text-xs font-bold tracking-[0.16em] text-cyan-700">FACTOR ABLATION</p><h2 className="mt-1 font-semibold">风险评分负向因子消融</h2><p className="mt-1 max-w-5xl text-xs leading-5 text-slate-600">每次仅移除一项信号日风险贡献，固定保留当前自动/回退扣分权重、候选范围、资金、成本和唯一退出策略，不重新用未来结果调权。Δ收益为“移除该因子”相对完整风险扣分策略的变化；Δ回撤为正代表移除后回撤更大，负代表回撤更小。判断核心负向因子须以样本外同时满足收益改善且回撤下降为准。</p></div></div><div className={`mt-4 rounded-xl border p-3 text-xs leading-5 ${stableNegativeFactors.length > 0 ? "border-rose-200 bg-rose-50 text-rose-900" : "border-emerald-200 bg-emerald-50 text-emerald-900"}`}>{stableNegativeFactors.length > 0 ? <>已在全周期及样本外一致复现的核心负向因子：<b>{stableNegativeFactors.map((factor) => factor.label).join("、")}</b>。这些因子可进入下一轮训练期权重再标定候选。</> : <>当前没有在全周期与严格样本外同时复现的核心负向因子。{fullCycleOnlyNegativeFactors.length > 0 && <>连板高度、日线成交额等仅呈现<strong>全周期表象负向</strong>，但移除后样本外收益下降且回撤上升，因此暂不应降低或删除其权重。</>}</>}</div><div className="mt-4 overflow-auto rounded-xl border border-cyan-100"><table className="w-full min-w-[1180px] text-xs"><thead className="bg-cyan-50 text-left text-cyan-900"><tr><th className="px-3 py-2">风险因子</th><th className="px-3 py-2">受影响信号 / 平均扣分</th><th className="px-3 py-2">全周期 Δ收益</th><th className="px-3 py-2">全周期 Δ回撤</th><th className="px-3 py-2">样本外 Δ收益</th><th className="px-3 py-2">样本外 Δ回撤</th><th className="px-3 py-2">结论</th></tr></thead><tbody>{sortedFactorAblations.map((factor) => { const fullCycleImproves = factor.fullCycle.returnDelta > 0 && factor.fullCycle.drawdownDelta < 0; const outOfSampleImproves = factor.walkForward.returnDelta > 0 && factor.walkForward.drawdownDelta < 0; const verdict = fullCycleImproves && outOfSampleImproves ? "负向因子已在样本外复现" : fullCycleImproves ? "全周期表象负向，样本外未复现" : outOfSampleImproves ? "样本外待复核负向" : factor.affectedSignalCount === 0 ? "当前样本未触发" : "未见稳定负向证据"; return <tr key={factor.key} className="border-t border-slate-100"><td className="px-3 py-2 font-medium text-slate-800">{factor.label}</td><td className="px-3 py-2">{factor.affectedSignalCount} / {factor.averageContribution}</td><td className={`px-3 py-2 font-medium ${factor.fullCycle.returnDelta >= 0 ? "text-rose-600" : "text-emerald-700"}`}>{factor.fullCycle.returnDelta >= 0 ? "+" : ""}{factor.fullCycle.returnDelta}%</td><td className={`px-3 py-2 font-medium ${factor.fullCycle.drawdownDelta <= 0 ? "text-rose-600" : "text-emerald-700"}`}>{factor.fullCycle.drawdownDelta >= 0 ? "+" : ""}{factor.fullCycle.drawdownDelta}%</td><td className={`px-3 py-2 font-medium ${factor.walkForward.returnDelta >= 0 ? "text-rose-600" : "text-emerald-700"}`}>{factor.walkForward.returnDelta >= 0 ? "+" : ""}{factor.walkForward.returnDelta}%</td><td className={`px-3 py-2 font-medium ${factor.walkForward.drawdownDelta <= 0 ? "text-rose-600" : "text-emerald-700"}`}>{factor.walkForward.drawdownDelta >= 0 ? "+" : ""}{factor.walkForward.drawdownDelta}%</td><td className="px-3 py-2 text-slate-600">{verdict}</td></tr>; })}</tbody></table></div></div></section>}
    <div className="mx-auto max-w-7xl space-y-5 px-4 pt-7 sm:px-6">
      <section className="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm sm:p-7"><div className="flex flex-col gap-4 lg:flex-row lg:items-end lg:justify-between"><div><div className="flex items-center gap-2 text-sky-700"><BarChart3 className="h-5 w-5" /><span className="text-xs font-bold tracking-[0.18em]">PORTFOLIO BACKTEST</span></div><h1 className="mt-2 text-2xl font-bold tracking-tight sm:text-3xl">组合资金回测</h1><p className="mt-2 max-w-3xl text-sm leading-6 text-slate-600">以候选信号为基础，模拟T+1开盘买入及实际交易日出清。唯一退出口径为动态止盈、开盘止损与强势续持；所有判断仅使用当日及之前可见的信息。</p></div><div className="rounded-xl border border-sky-100 bg-sky-50 px-4 py-3 text-right"><p className="text-xs text-sky-700">当前候选口径</p><p className="mt-1 font-semibold text-sky-900">1–4板 · T+1开盘入场</p></div></div></section>

      <section className="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm"><div className="mb-4 flex items-center gap-2"><WalletCards className="h-5 w-5 text-violet-700" /><div><h2 className="font-semibold">回测参数</h2><p className="text-xs text-slate-500">修改参数后自动重新计算；成交金额仍受整手、资金和最大持仓限制。</p></div></div>
        <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4 xl:grid-cols-6">
          <label className="text-xs text-slate-600">初始资金<input type="number" min="1000" step="1000" value={config.initialCapital} onChange={(event) => update("initialCapital", Number(event.target.value) || 0)} className="mt-1 h-9 w-full rounded-md border border-slate-200 px-2" /></label><label className="text-xs text-slate-600">最大持仓数<input type="number" min="1" max="100" value={config.maxPositions} onChange={(event) => update("maxPositions", Number(event.target.value) || 1)} className="mt-1 h-9 w-full rounded-md border border-slate-200 px-2" /></label><label className="text-xs text-slate-600">佣金(bps)<input type="number" min="0" step="0.1" value={config.commissionBps} onChange={(event) => update("commissionBps", Number(event.target.value) || 0)} className="mt-1 h-9 w-full rounded-md border border-slate-200 px-2" /></label><label className="text-xs text-slate-600">印花税(bps)<input type="number" min="0" step="0.1" value={config.stampDutyBps} onChange={(event) => update("stampDutyBps", Number(event.target.value) || 0)} className="mt-1 h-9 w-full rounded-md border border-slate-200 px-2" /></label><label className="text-xs text-slate-600">过户费(bps)<input type="number" min="0" step="0.1" value={config.transferFeeBps} onChange={(event) => update("transferFeeBps", Number(event.target.value) || 0)} className="mt-1 h-9 w-full rounded-md border border-slate-200 px-2" /></label><label className="text-xs text-slate-600">双边滑点(bps)<input type="number" min="0" step="1" value={config.slippageBps} onChange={(event) => update("slippageBps", Number(event.target.value) || 0)} className="mt-1 h-9 w-full rounded-md border border-slate-200 px-2" /></label>
        </div>
        <div className="mt-4 grid gap-3 lg:grid-cols-3"><div className="rounded-xl border border-sky-100 bg-sky-50/60 p-3"><p className="text-xs font-semibold text-sky-900">T+1开盘预期过滤</p><p className="mt-1 text-xs text-sky-700">相对信号日收盘严格低于阈值时不买入。</p><label className="mt-2 block text-xs text-slate-600">最低开盘涨幅(%)<input type="number" min="-50" max="100" step="0.5" value={config.minimumExpectedOpenChangePercent} onChange={(event) => update("minimumExpectedOpenChangePercent", Math.min(100, Math.max(-50, Number(event.target.value) || 0)))} className="mt-1 h-8 w-28 rounded-md border border-slate-200 bg-white px-2" /></label></div><div className="rounded-xl border border-violet-100 bg-violet-50/60 p-3"><p className="text-xs font-semibold text-violet-900">分仓策略</p><p className="mt-1 text-xs text-violet-700">等权、评分加权或固定单笔比例。</p><select value={config.positionSizingStrategy} onChange={(event) => update("positionSizingStrategy", event.target.value === "scoreWeighted" ? "scoreWeighted" : event.target.value === "fixedPercent" ? "fixedPercent" : "equal")} className="mt-2 h-8 rounded-md border border-slate-200 bg-white px-2 text-xs"><option value="equal">等权分仓</option><option value="scoreWeighted">评分加权</option><option value="fixedPercent">固定单笔比例</option></select><label className="ml-2 text-xs text-slate-600">比例<input type="number" min="1" max="100" disabled={config.positionSizingStrategy !== "fixedPercent"} value={config.fixedPositionPercent} onChange={(event) => update("fixedPositionPercent", Math.min(100, Math.max(1, Number(event.target.value) || 1)))} className="ml-1 h-8 w-16 rounded-md border border-slate-200 bg-white px-2 disabled:bg-slate-100" />%</label></div><div className="rounded-xl border border-amber-100 bg-amber-50/60 p-3"><p className="text-xs font-semibold text-amber-900">成交限制</p><label className="mt-2 flex items-center gap-2 text-xs text-slate-700"><input type="checkbox" checked={config.blockLimitUpBuys} onChange={(event) => update("blockLimitUpBuys", event.target.checked)} />限制涨停追买</label><label className="mt-2 flex items-center gap-2 text-xs text-slate-700"><input type="checkbox" checked={config.blockLimitDownSells} onChange={(event) => update("blockLimitDownSells", event.target.checked)} />限制一字跌停卖出</label><label className="mt-2 flex items-center gap-2 text-xs text-slate-700"><input type="checkbox" disabled={!config.blockLimitDownSells} checked={config.enableOneWordLimitDownProbability} onChange={(event) => update("enableOneWordLimitDownProbability", event.target.checked)} />启用概率成交</label></div></div>
        <div className="mt-3 rounded-xl border border-amber-100 bg-amber-50/60 p-3"><div className="flex flex-wrap items-end gap-3"><div className="mr-auto"><p className="text-xs font-semibold text-amber-900">一字跌停保守成交概率</p><p className="mt-1 text-xs text-amber-700">仅在“限制一字跌停卖出”和“启用概率成交”均开启时生效；未成交仓位会在后续实际交易日继续尝试出清。</p></div><label className="text-xs text-slate-600">卖出成交概率(%)<input type="number" min="0" max="100" step="1" disabled={!config.blockLimitDownSells || !config.enableOneWordLimitDownProbability} value={config.oneWordLimitDownSellProbability} onChange={(event) => update("oneWordLimitDownSellProbability", Math.min(100, Math.max(0, Number(event.target.value) || 0)))} className="mt-1 block h-8 w-28 rounded-md border border-slate-200 bg-white px-2 disabled:bg-slate-100" /></label></div></div>
        <div className="mt-3 rounded-xl border border-rose-100 bg-rose-50/50 p-3"><div className="flex flex-wrap items-end gap-3"><div className="mr-auto"><p className="text-xs font-semibold text-rose-900">唯一退出策略：动态止盈、止损与强势续持</p><p className="mt-1 text-xs text-rose-700">从T+2起：开盘触发止损即按开盘出清；收盘达到启动浮盈后从持仓期最高收盘价回撤则止盈；未启动止盈时仅满足强势续持条件才继续持有。</p></div><label className="text-xs text-slate-600">启动浮盈<input type="number" value={config.trailingProfitActivationPercent} onChange={(event) => update("trailingProfitActivationPercent", Math.min(100, Math.max(0, Number(event.target.value) || 0)))} className="mt-1 block h-8 w-20 rounded-md border border-slate-200 bg-white px-2" /></label><label className="text-xs text-slate-600">回撤阈值<input type="number" value={config.trailingDrawdownPercent} onChange={(event) => update("trailingDrawdownPercent", Math.min(100, Math.max(0, Number(event.target.value) || 0)))} className="mt-1 block h-8 w-20 rounded-md border border-slate-200 bg-white px-2" /></label><label className="text-xs text-slate-600">止损<input type="number" value={config.stopLossPercent} onChange={(event) => update("stopLossPercent", Math.min(100, Math.max(0, Number(event.target.value) || 0)))} className="mt-1 block h-8 w-20 rounded-md border border-slate-200 bg-white px-2" /></label><label className="text-xs text-slate-600">续持阈值<input type="number" value={config.strongHoldMinReturn} onChange={(event) => update("strongHoldMinReturn", Math.min(100, Math.max(0, Number(event.target.value) || 0)))} className="mt-1 block h-8 w-20 rounded-md border border-slate-200 bg-white px-2" /></label><label className="text-xs text-slate-600">最多持有日<input type="number" min="2" max="30" value={config.maxHoldingDays} onChange={(event) => update("maxHoldingDays", Math.min(30, Math.max(2, Math.floor(Number(event.target.value) || 2))))} className="mt-1 block h-8 w-20 rounded-md border border-slate-200 bg-white px-2" /></label></div></div>
        <div className="mt-3 rounded-xl border border-fuchsia-100 bg-fuchsia-50/50 p-3"><div className="flex flex-wrap items-end gap-3"><div className="mr-auto"><p className="text-xs font-semibold text-fuchsia-900">下行风险研究参数</p><p className="mt-1 max-w-3xl text-xs text-fuchsia-800">原始、风险扣分和高风险过滤三版实验共享上方唯一退出策略；风险分只读取信号日字段，T+1开盘后的低价路径仅用于事后标签。自动寻优仅在训练窗口比较预设权重网格，选中权重只进入紧随其后的验证窗口。默认45日训练、14日验证，按当前行情覆盖形成10个连续无重叠样本外窗口。</p></div><label className="flex items-center gap-2 self-center text-xs font-medium text-fuchsia-900"><input type="checkbox" checked={config.autoTunePenaltyWeight} onChange={(event) => update("autoTunePenaltyWeight", event.target.checked)} />自动寻优</label><label className="text-xs text-slate-600">观察日<input type="number" min="2" max="10" value={config.downsideObservationDays} onChange={(event) => update("downsideObservationDays", Math.min(10, Math.max(2, Math.floor(Number(event.target.value) || 2))))} className="mt-1 block h-8 w-20 rounded-md border border-slate-200 bg-white px-2" /></label><label className="text-xs text-slate-600">中档下行<input type="number" min="1" max="50" value={config.mediumDownsidePercent} onChange={(event) => update("mediumDownsidePercent", Math.min(50, Math.max(1, Number(event.target.value) || 1)))} className="mt-1 block h-8 w-20 rounded-md border border-slate-200 bg-white px-2" /></label><label className="text-xs text-slate-600">高档下行<input type="number" min="1" max="50" value={config.highDownsidePercent} onChange={(event) => update("highDownsidePercent", Math.max(config.mediumDownsidePercent, Math.min(50, Number(event.target.value) || config.mediumDownsidePercent)))} className="mt-1 block h-8 w-20 rounded-md border border-slate-200 bg-white px-2" /></label><label className="text-xs text-slate-600">手动回退权重<input type="number" min="0" max="1" step="0.05" disabled={config.autoTunePenaltyWeight} value={config.riskPenaltyWeight} onChange={(event) => update("riskPenaltyWeight", Math.min(1, Math.max(0, Number(event.target.value) || 0)))} className="mt-1 block h-8 w-24 rounded-md border border-slate-200 bg-white px-2 disabled:bg-slate-100" /></label><label className="text-xs text-slate-600">硬过滤分<input type="number" min="0" max="100" value={config.hardRiskThreshold} onChange={(event) => update("hardRiskThreshold", Math.min(100, Math.max(0, Number(event.target.value) || 0)))} className="mt-1 block h-8 w-20 rounded-md border border-slate-200 bg-white px-2" /></label><label className="text-xs text-slate-600">训练窗口<input type="number" min="30" max="150" value={config.rollingTrainTradingDays} onChange={(event) => update("rollingTrainTradingDays", Math.min(150, Math.max(30, Math.floor(Number(event.target.value) || 30))))} className="mt-1 block h-8 w-20 rounded-md border border-slate-200 bg-white px-2" /></label><label className="text-xs text-slate-600">验证窗口<input type="number" min="10" max="60" value={config.rollingValidationTradingDays} onChange={(event) => update("rollingValidationTradingDays", Math.min(60, Math.max(10, Math.floor(Number(event.target.value) || 10))))} className="mt-1 block h-8 w-20 rounded-md border border-slate-200 bg-white px-2" /></label></div></div>
      </section>
      {isLoading || !simulation ? <div className="flex min-h-72 items-center justify-center rounded-2xl border border-slate-200 bg-white"><Loader2 className="h-7 w-7 animate-spin text-sky-600" /></div> : <>
        <section className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-6"><Metric label="期末资金（全样本原始基准）" value={`¥${formatMoney(simulation.finalCapital)}`} /><Metric label="全样本原始收益（未扣风险分）" value={`¥${formatMoney(simulation.netProfit)} / ${simulation.totalReturn}%`} tone={simulation.netProfit >= 0 ? "text-rose-600" : "text-emerald-700"} /><Metric label="胜率 / 盈亏比" value={`${simulation.winRate ?? "-"}% / ${simulation.profitFactor ?? "-"}`} /><Metric label="最大回撤（原始基准）" value={`${simulation.maxDrawdown}%`} tone="text-emerald-700" /><Metric label="入场 / 已出清" value={`${simulation.filledCount} / ${simulation.completedCount}`} />{walkForwardRiskPenalty && <Metric label="样本外风险扣分收益" value={`${walkForwardRiskPenalty.totalReturn}% / 回撤${walkForwardRiskPenalty.maxDrawdown}%`} tone={walkForwardRiskPenalty.totalReturn >= 0 ? "text-rose-600" : "text-emerald-700"} />}</section>
        {downsideRiskResearch && marketFactorCoverage && <section data-market-factor-coverage className="rounded-2xl border border-sky-200 bg-white p-5 shadow-sm"><div className="flex flex-wrap items-start gap-3"><DatabaseZap className="mt-0.5 h-5 w-5 text-sky-700" /><div className="mr-auto"><p className="text-xs font-bold tracking-[0.16em] text-sky-700">MARKET FACTOR COVERAGE</p><h2 className="mt-1 font-semibold">市场因子数据覆盖</h2><p className="mt-1 max-w-4xl text-xs leading-5 text-slate-600">市场风险因子严格读取候选自身信号日：项目涨停数来自已录入的全表记录，沪深成交额来自 Tushare daily 聚合，两融余额来自上交所与深交所公开汇总文件。未验证或缺失的成交额、两融余额均按<strong>零贡献</strong>处理，不以占位值填补。</p></div></div><div className="mt-4 grid gap-3 sm:grid-cols-2 xl:grid-cols-5"><Metric label="回测信号日" value={`${marketFactorCoverage.signalDateCount} 日`} /><Metric label="项目涨停数覆盖" value={`${marketFactorCoverage.limitUpCountDateCount} / ${marketFactorCoverage.signalDateCount}`} /><Metric label="已验证市场数据" value={`${marketFactorCoverage.verifiedMarketDataDateCount} / ${marketFactorCoverage.signalDateCount}`} tone="text-sky-700" /><Metric label="沪深成交额覆盖" value={`${marketFactorCoverage.turnoverDateCount} / ${marketFactorCoverage.signalDateCount}`} /><Metric label="两融余额覆盖" value={`${marketFactorCoverage.marginBalanceDateCount} / ${marketFactorCoverage.signalDateCount}`} /></div><p className="mt-3 text-xs leading-5 text-slate-500">覆盖日期：{marketFactorCoverage.startDate ?? "-"} 至 {marketFactorCoverage.endDate ?? "-"}。两融余额可用样本 {downsideRiskResearch.marginBalanceSampleSize} 个，其中相对前20个历史已验证日期可比较 {downsideRiskResearch.marginBalanceComparableSampleSize} 个；该项仅衡量绝对偏离，不解释为杠杆方向或资金净流入。</p></section>}
        {downsideRiskResearch && <section className="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm"><div className="flex flex-wrap items-start gap-3"><ShieldAlert className="mt-0.5 h-5 w-5 text-fuchsia-700" /><div className="mr-auto"><h2 className="font-semibold">下行风险评分实验框架</h2><p className="mt-1 max-w-4xl text-xs leading-5 text-slate-500">{downsideRiskResearch.definition} 当前展示 {downsideRiskResearch.labeledSampleSize} 个完整观察期的样本外候选；原始、风险扣分和高风险过滤三版均使用唯一的动态止盈、开盘止损与强势续持退出策略。</p></div></div><div className="mt-4 grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><Metric label="日线覆盖" value={`${dailyPriceCoverage?.rowCount ?? 0} 行`} /><Metric label="日期范围" value={`${dailyPriceCoverage?.startDate ?? "-"} 至 ${dailyPriceCoverage?.endDate ?? "-"}`} /><Metric label="低价覆盖" value={`${dailyPriceCoverage?.lowPriceCount ?? 0} / ${dailyPriceCoverage?.rowCount ?? 0}`} /><Metric label="成交额覆盖" value={`${dailyPriceCoverage?.amountCount ?? 0} / ${dailyPriceCoverage?.rowCount ?? 0}`} /></div><p className="mt-3 text-xs leading-5 text-slate-500">低价标签完整样本 {downsideRiskResearch.lowPriceLabelSampleSize} 个；信号日成交额可用样本 {downsideRiskResearch.signalAmountSampleSize} 个。{downsideRiskResearch.autoTunePenaltyWeight && <span className="font-medium text-fuchsia-800"> 自动寻优网格：{downsideRiskResearch.penaltyWeightGrid.join("、")}；训练目标 = 收益率 − 0.5 × 最大回撤，依次以收益、回撤、已出清笔数和更小权重决胜。</span>}{downsideRiskResearch.labeledSampleSize < 50 && <span className="font-medium text-amber-700"> 当前完整观察期样本少于50个，仅适合观察特征方向。</span>}</p><div className="mt-4 grid gap-2 sm:grid-cols-2 xl:grid-cols-4">{downsideRiskResearch.featureMatrix.map((feature) => <div key={feature.key} className="rounded-lg border border-slate-200 bg-slate-50 p-3"><div className="flex items-center justify-between gap-2"><p className="text-xs font-semibold text-slate-800">{feature.label}</p><span className="rounded bg-white px-1.5 py-0.5 text-[10px] font-medium text-slate-500">{feature.timing}</span></div><p className="mt-1 text-xs leading-5 text-slate-500">{feature.definition}</p></div>)}</div><div className="mt-5 overflow-auto rounded-xl border border-slate-200"><table className="w-full min-w-[720px] text-xs"><thead className="bg-slate-100 text-left text-slate-500"><tr><th className="px-3 py-2">风险分层</th><th className="px-3 py-2">样本数</th><th className="px-3 py-2">平均最大不利波动</th><th className="px-3 py-2">≤ -{downsideRiskResearch.mediumDownsidePercent}%</th><th className="px-3 py-2">≤ -{downsideRiskResearch.highDownsidePercent}%</th></tr></thead><tbody>{downsideRiskResearch.riskTiers.map((tier) => <tr key={tier.tier} className="border-t border-slate-100"><td className="px-3 py-2 font-medium text-slate-800">{tier.tier}</td><td className="px-3 py-2">{tier.sampleSize}</td><td className="px-3 py-2 text-emerald-700">{tier.averageMaxAdverseReturn ?? "-"}{tier.averageMaxAdverseReturn === null ? "" : "%"}</td><td className="px-3 py-2">{tier.mediumDownsideCount} / {tier.mediumDownsideRate ?? "-"}%</td><td className="px-3 py-2">{tier.highDownsideCount} / {tier.highDownsideRate ?? "-"}%</td></tr>)}</tbody></table></div><div className="mt-5 grid gap-3 md:grid-cols-3">{downsideRiskResearch.experiments.map((experiment) => <div key={experiment.key} className="rounded-xl border border-slate-200 bg-slate-50/70 p-3"><div className="flex items-start justify-between gap-3"><div><p className="text-sm font-semibold text-slate-800">{experiment.label}</p><p className="mt-1 min-h-10 text-xs leading-5 text-slate-500">{experiment.description}</p></div><span className={experiment.realisticSimulation.totalReturn >= 0 ? "text-sm font-bold text-rose-600" : "text-sm font-bold text-emerald-700"}>{experiment.realisticSimulation.totalReturn}%</span></div><div className="mt-3 grid grid-cols-3 gap-2 border-t border-slate-200 pt-3 text-xs"><div><p className="text-slate-400">最大回撤</p><p className="mt-1 font-semibold text-emerald-700">{experiment.realisticSimulation.maxDrawdown}%</p></div><div><p className="text-slate-400">候选/剔除</p><p className="mt-1 font-semibold text-slate-700">{experiment.inputCandidateCount}/{experiment.excludedCandidateCount}</p></div><div><p className="text-slate-400">胜率</p><p className="mt-1 font-semibold text-slate-700">{experiment.realisticSimulation.winRate ?? "-"}%</p></div></div></div>)}</div><ReturnLineChart data={downsideRiskCurve} series={downsideRiskResearch.experiments.map((item) => ({ key: item.key, label: item.label, color: item.key === "baseline" ? "#64748b" : item.key === "riskPenalty" ? "#d946ef" : "#f59e0b" }))} /><div className="mt-5 rounded-xl border border-slate-200"><div className="flex items-center gap-2 border-b border-slate-200 bg-slate-50 px-3 py-2"><DatabaseZap className="h-4 w-4 text-fuchsia-700" /><div><p className="text-sm font-semibold">滚动样本外窗口</p><p className="text-xs text-slate-500">每一行均以前置{downsideRiskResearch.rollingTrainTradingDays}个交易日校准、后续{downsideRiskResearch.rollingValidationTradingDays}个交易日验证；自动寻优只用校准期结果，不将验证期路径反向用于选权。</p></div></div><div className="overflow-auto"><table className="w-full min-w-[1360px] text-xs"><thead className="bg-white text-left text-slate-500"><tr><th className="px-3 py-2">窗口</th><th className="px-3 py-2">训练期</th><th className="px-3 py-2">验证期</th><th className="px-3 py-2">训练样本</th><th className="px-3 py-2">选出权重</th><th className="px-3 py-2">训练目标</th><th className="px-3 py-2">训练收益/回撤</th><th className="px-3 py-2">验证标签</th><th className="px-3 py-2">原始收益</th><th className="px-3 py-2">扣分收益</th><th className="px-3 py-2">过滤收益</th></tr></thead><tbody>{downsideRiskResearch.rollingWindows.map((window) => { const byKey = new Map(window.experiments.map((item) => [item.key, item])); return <tr key={window.index} className="border-t border-slate-100"><td className="px-3 py-2">{window.index}</td><td className="px-3 py-2">{window.calibrationStartDate} 至 {window.calibrationEndDate}</td><td className="px-3 py-2">{window.validationStartDate} 至 {window.validationEndDate}</td><td className="px-3 py-2">{window.trainingSampleSize}</td><td className="px-3 py-2 font-semibold text-fuchsia-800">{window.autoTunedPenaltyWeight}</td><td className="px-3 py-2">{window.trainingObjectiveValue}%</td><td className="px-3 py-2"><span className={window.trainingTotalReturn >= 0 ? "text-rose-600" : "text-emerald-700"}>{window.trainingTotalReturn}%</span> / <span className="text-emerald-700">{window.trainingMaxDrawdown}%</span></td><td className="px-3 py-2 text-emerald-700">{window.labeledSampleSize} / {window.highDownsideRate ?? "-"}%</td>{(["baseline", "riskPenalty", "hardFilter"] as const).map((key) => { const result = byKey.get(key)?.realisticSimulation.totalReturn; return <td key={key} className={`px-3 py-2 font-medium ${result !== undefined && result >= 0 ? "text-rose-600" : "text-emerald-700"}`}>{result ?? "-"}{result === undefined ? "" : "%"}</td>; })}</tr>; })}</tbody></table></div></div></section>}
        <section className="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm"><div className="flex items-start gap-2"><ShieldCheck className="mt-0.5 h-5 w-5 text-emerald-700" /><div><h2 className="font-semibold">资金与仓位审计</h2><p className="mt-1 text-sm text-slate-600">峰值持仓 {simulation.peakOpenPositionCount}/{simulation.assumptions.maxPositions}，最低可用现金 ¥{formatMoney(simulation.minimumCash)}。开盘止损释放的资金仅在同一开盘时点后参与候选排序；收盘出清资金不提前复用。</p></div></div></section>
        <FullOrdersSection
          strategy={orderStrategy}
          onStrategyChange={(strategy) => { setOrderStrategy(strategy); setReason("all"); }}
          activeStrategy={activeOrderStrategy}
          orders={orders}
          displayedOrders={displayedOrders}
          orderStatus={orderStatus}
          onOrderStatusChange={setOrderStatus}
          reason={reason}
          onReasonChange={setReason}
          reasons={reasons}
          keyword={keyword}
          onKeywordChange={setKeyword}
          returnSortDirection={orderReturnSortDirection}
          onReturnSortDirectionChange={setOrderReturnSortDirection}
        />
        {false && <>
        <section className="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm"><div className="mb-4 flex flex-wrap items-end gap-3"><div className="mr-auto"><h2 className="font-semibold">全部模拟订单</h2><p className="mt-1 text-xs text-slate-500">显示 {displayedOrders.length}/{orders.length} 笔；红涨绿跌。</p></div><label className="text-xs text-slate-600">状态<select value={orderStatus} onChange={(event) => setOrderStatus(event.target.value as "all" | "filled" | "skipped")} className="mt-1 block h-8 rounded-md border border-slate-200 px-2"><option value="all">全部</option><option value="filled">已入场</option><option value="skipped">未入场</option></select></label><label className="text-xs text-slate-600">原因<select value={reason} onChange={(event) => setReason(event.target.value)} className="mt-1 block h-8 max-w-48 rounded-md border border-slate-200 px-2"><option value="all">全部</option>{reasons.map((value) => <option key={value} value={value}>{value}</option>)}</select></label><label className="text-xs text-slate-600">搜索<Input value={keyword} onChange={(event) => setKeyword(event.target.value)} placeholder="代码或名称" className="mt-1 h-8 w-36" /></label></div><div className="overflow-auto rounded-lg border border-slate-200"><table className="w-full min-w-[1100px] text-xs"><thead className="bg-slate-100 text-left text-slate-500"><tr><th className="px-3 py-2">信号日</th><th className="px-3 py-2">股票</th><th className="px-3 py-2">状态</th><th className="px-3 py-2">股数</th><th className="px-3 py-2">买入/卖出日</th><th className="px-3 py-2">买入/卖出价</th><th className="px-3 py-2">收益率</th><th className="px-3 py-2">买点涨幅</th><th className="px-3 py-2">原因</th></tr></thead><tbody>{displayedOrders.map((order, index) => { const entryPointPremium = order.entryPointPremium ?? null; return <tr key={`${order.signalDate}-${order.stockCode}-${index}`} className="border-t border-slate-100"><td className="px-3 py-2">{formatDate(order.signalDate)}</td><td className="px-3 py-2"><p className="font-medium">{order.stockName}</p><p className="font-mono text-slate-400">{order.stockCode}</p></td><td className="px-3 py-2">{order.status === "filled" ? "已成交" : "未成交"}</td><td className="px-3 py-2">{order.shares || "-"}</td><td className="px-3 py-2">{formatDate(order.entryDate)} / {formatDate(order.exitDate)}</td><td className="px-3 py-2">{order.entryPrice ?? "-"} / {order.exitPrice ?? "-"}</td><td className={`px-3 py-2 ${order.netReturn !== null && order.netReturn >= 0 ? "text-rose-600" : "text-emerald-700"}`}>{order.netReturn === null ? "-" : `${order.netReturn}%`}</td><td className={`px-3 py-2 ${entryPointPremium !== null && entryPointPremium >= 0 ? "text-rose-600" : "text-emerald-700"}`}>{entryPointPremium === null ? "-" : `${entryPointPremium}%`}</td><td className="max-w-72 px-3 py-2 text-slate-500">{order.reason ?? "-"}</td></tr>; })}</tbody></table></div></section>
        </>}
      </>}
    </div>
  </main>;
}
